const UNDERLAYER_PALETTE_TRIGGERS = {
  topUnderlayerColorId: 'gestureId',
  bottomUnderlayerColorId: 'bottomRiseId',
};

function underlayerColorControl(inner) {
  if (!inner?.item) return null;
  return {
    key: inner.colorKey,
    label: inner.colorKey === 'topUnderlayerColorId' ? '上身內搭配色' : '下身內搭配色',
    options: [{ id: 'none', zh: '無', en: '' }, ...inner.colors],
  };
}

const underlayerTrigger = UNDERLAYER_PALETTE_TRIGGERS[activeWardrobePickerKey];
const activeWardrobePickerControl = underlayerTrigger
  ? underlayerColorControl(underlayerField(locks, lockControls, underlayerTrigger))
  : [...characterLockControls, ...wardrobeLockControls].find(control => control.key === activeWardrobePickerKey);

if (rawControl.key === 'bottomRiseId' && !underlayerField({ ...locks, bottomRiseId: THIGH_RISE.id }, lockControls, 'bottomRiseId')) {
  rawControl = { ...rawControl, options: rawControl.options.filter(option => option.id !== THIGH_RISE.id),
    ...(locks.bottomRiseId === THIGH_RISE.id ? { closureDisplayValue: 'none' } : {}) };
}

const inner = !disabled && underlayerField(locks, lockControls, control.key);
if (inner) {
  const isUpper = control.key === 'gestureId';
  const label = isUpper ? '上身內搭' : '下身內搭';
  const palette = underlayerColorControl(inner);
  const pair = (
    <div className="manual-underlayer-pair">
      <SelectControlField
        control={{ key: inner.itemKey, label, suppressDefaultRandomOption: true,
          options: [{ id: 'none', zh: '無', en: '' }, ...inner.items] }}
        value={inner.item?.id || 'none'}
        onChange={id => updateLocks({ [inner.itemKey]: id })}
        onCopy={text => handleCopyText(label, text)}
      />
      {palette && (
        <WardrobePickerField
          control={palette}
          value={inner.color?.id || 'none'}
          onOpen={() => openWardrobePicker(palette)}
          onCopy={text => handleCopyText(palette.label, text)}
        />
      )}
    </div>
  );
  return isUpper
    ? <div key={control.key} className="manual-underlayer-fields">{field}{pair}</div>
    : <Fragment key={control.key}>{field}{pair}</Fragment>;
}

.manual-underlayer-fields,
.manual-underlayer-pair {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 10px;
}
.manual-underlayer-fields { grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr); }
.manual-underlayer-fields > .manual-underlayer-pair { grid-column: auto; }
.manual-underlayer-fields > .field,
.manual-underlayer-pair > .field { min-width: 0; }
@media (max-width: 820px) {
  .manual-underlayer-fields { grid-template-columns: minmax(0, 1fr); }
}

.wardrobe-picker-modal--underlayer .wardrobe-picker-color-grid {
  grid-auto-rows: max-content;
  align-content: start;
}

}

function getSingleBottomRiseOption(id) {
  return id === THIGH_RISE.id ? THIGH_RISE : getBottomRiseOption(id);

function withUnderlayer(text, host) {
  const layer = host?.meta?.underlayer;
  if (!text || !layer) return text;
  const source = composeItemWearableColorPrompt(layer.item, layer.item.en, layer.color);
  if (layer.loweredOuter) return text + '. Underneath she wears ' + source + ', fully visible and still worn on her hips';
  return text + ', layered over ' + source + (layer.relation ? ', ' + layer.relation : '');
}

for (const host of wardrobe) {
  const layer = host.meta?.underlayer;
  if (!layer) continue;
  const top = host.id === context.locks.topId;
  snapshot[top ? 'topUnderlayerId' : 'bottomUnderlayerId'] = layer.item.id;
  if (layer.color) snapshot[top ? 'topUnderlayerColorId' : 'bottomUnderlayerColorId'] = layer.color.id;
}

export function mouthHeldHemText(underlayerName) {
  const visibility = underlayerName
    ? `The ${underlayerName} underneath ${underlayerName.endsWith('pasties') ? 'are' : 'is'} fully visible.`
    : '';
  return [
    'She holds the center of the front hem of her top between her teeth.',
    'The lifted front panel fans out from her mouth in one continuous triangular fold, with the fabric gathered high across her collarbones.',
    visibility,
    'Both hands rest behind her back.',
  ].filter(Boolean).join(' ');
}

